var a=`1070-carrot-cake-chai-tow-kway`;var t=`world-1070`;var n=`SG`;var o=`southeast-asia`;var r=8;var s=86;var l={en:`Carrot Cake (Chai Tow Kway)`,ua:`Смажений пиріг із дайконом`};var d={en:`Carrot Cake (Chai Tow Kway) is a dish from Singapore prepared with daikon, rice flour, chicken egg, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used. Pickled daikon replaces traditionally preserved radish. The dish is a savory daikon-rice cake, not a carrot dessert.`,ua:`Смажений пиріг із дайконом, страва кухні країни Сінгапур, яку готують із таких продуктів: дайкон, рисове борошно, куряче яйце, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Маринований дайкон замінює традиційний консервований редис. Страва, несолодкий корж із дайкону, а не морквяний десерт.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:10,i:[[`daikon`,620,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`rice-flour`,230,`g`],[`water`,290,`ml`],[`table-salt`,5,`g`]]},{en:`Steam the radish-rice-flour batter in a shallow greased tray until firm, cool until sliceable, then cube for stir-frying.`,ua:`Пропарте тісто з дайкону й рисового борошна в неглибокій змащеній формі до застигання, остудіть і наріжте кубиками для обсмаження.`,t:[`steaming`],m:45,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`chicken-egg`,4,`pcs`],[`garlic`,4,`clove`],[`sunflower-oil`,55,`ml`],[`pickled-daikon`,60,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,40,`g`],[`light-soy-sauce`,30,`ml`]]}];var h={slug:a,id:t,country:`SG`,region:o,servings:8,minutes:86,title:l,text:d,steps:g};export{n as country,h as default,t as id,s as minutes,o as region,r as servings,a as slug,g as steps,d as text,l as title};